// ---------------- runtime glue ----------------
static double* arena = 0;
static size_t arena_sz = 0;
static double* get_arena(size_t bytes){
  if (bytes > arena_sz){
    if (arena) free(arena);
    size_t sz = (bytes + (2u<<20) - 1) & ~(size_t)((2u<<20) - 1);
    arena = (double*)aligned_alloc(2u<<20, sz);
    madvise(arena, sz, MADV_HUGEPAGE);
    memset(arena, 0, sz);
    arena_sz = bytes;
  }
  return arena;
}

